"""Real-browser regression for session isolation, persistence and multi-panel UI."""
import json,subprocess,time,re
from pathlib import Path
session='asset-ui-regression';logs=[];checks={};start=time.monotonic();root=Path(__file__).resolve().parents[2];output=root/'experiments/04-ui-implementation';output.mkdir(exist_ok=True)
def cli(*args):
 p=subprocess.run(['agent-browser','--session',session,*args],text=True,capture_output=True);logs.append({'argv':args,'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr});assert p.returncode==0,p.stderr;return p.stdout
def ev(js):return json.loads(cli('eval',js))
def poll(js,timeout=12):
 before=time.monotonic()
 while time.monotonic()-before<timeout:
  if ev(js):return
  time.sleep(.12)
 raise AssertionError(js)
def clickText(selector,value):cli('eval',f"[...document.querySelectorAll({json.dumps(selector)})].filter(el=>el.getClientRects().length>0).find(el=>el.textContent.includes({json.dumps(value)})).click();void 0")
def send(text):
 count=ev("document.querySelectorAll('.chat-message.assistant').length");cli('fill','textarea[aria-label="Message Asset Copilot"]',text);cli('click','button[aria-label="Send message"]');poll("document.querySelectorAll('.chat-message.assistant').length>"+str(count));poll("!document.querySelector('button[aria-label=\"Stop response\"]')");poll("[...document.querySelectorAll('.chat-message.assistant')].at(-1).querySelector('.message-actions')!==null")
def test(name,fn):
 try:fn();checks[name]={'passed':True}
 except Exception as e:checks[name]={'passed':False,'error':str(e),'text':ev('document.body.innerText')[-1800:]}
def sample():
 cli('click','.suggestion-card:first-child');poll("document.querySelectorAll('[data-panel]').length===6");poll("!document.querySelector('button[aria-label=\"Stop response\"]')");assert ev("document.querySelector('.header-leading strong').textContent.startsWith('Show a sample fleet')")
 time.sleep(.7);cli('screenshot',str(output/'conversation-desktop.png'));assert ev("document.querySelector('.leaflet-container')!==null");poll("document.querySelectorAll('.analytics-chart svg').length===3")
def selection():
 cli('eval',"document.querySelector('[data-panel=table] tr[data-row-key^=SAMPLE-02] button').click();void 0");poll("document.querySelector('.selection-note').textContent.includes('SAMPLE-02')");assert ev("document.querySelector('[data-panel=status]').textContent.includes('24')")
 cli('eval',"document.querySelector('[data-panel=status] .source-link').click();void 0");poll("document.querySelector('.ant-drawer-open')!==null");assert ev("document.querySelector('.ant-drawer-open').textContent.includes('Sample weekly inspection')");cli('screenshot',str(output/'evidence-desktop.png'));cli('press','Escape');time.sleep(.5);poll("!document.querySelector('.ant-drawer-open')");cli('eval',"document.querySelector('.selection-note button').click();void 0")
def mapkeyboard():
 poll("!document.querySelector('.selection-note') && !!document.querySelector('.leaflet-interactive[tabindex=\"0\"]')");time.sleep(.5)
 cli('eval',"document.querySelector('[data-panel=map]').scrollIntoView({block:'center'});document.querySelector('.leaflet-interactive').focus();void 0");assert ev("document.activeElement?.getAttribute('aria-label')?.includes('SAMPLE-01')");cli('press','Enter');poll("document.querySelector('.selection-note')?.textContent.includes('SAMPLE-01') && !!document.querySelector('.asset-map-popup')");cli('click','.asset-map-popup button');poll("!!document.querySelector('.ant-drawer-open')");assert ev("document.querySelector('.ant-drawer-open').textContent.includes('Sample weekly inspection')");cli('press','Escape');poll("!document.querySelector('.ant-drawer-open')");poll("!document.querySelector('.ant-drawer-mask-motion-leave')");cli('eval',"document.querySelector('.selection-note button').click();document.querySelector('.leaflet-popup-close-button')?.click();void 0")
def sessions():
 cli('click','.new-conversation');poll("document.querySelector('.welcome')!==null");send('Show temperature trends');assert ev("document.querySelector('.header-leading strong').textContent==='Show temperature trends'");assert ev("document.querySelectorAll('[data-panel]').length===3")
 cli('open','http://localhost:5190');poll("document.querySelectorAll('[data-panel]').length===3");assert ev("document.querySelector('.user-bubble').textContent==='Show temperature trends'")
